-- =====================================================================
-- V8: 조직을 가상 조직으로 바꾸고 기업·기관·대학 공유 플랫폼용 시연 장비를 추가
--  * 기존 기관 9곳의 이름을 가상 이름으로 바꿈 (id 는 그대로라 기존 장비·의뢰·계정 연결 유지).
--    대학 부설 2곳은 유형을 UNIVERSITY 로 변경
--  * 새 가상 조직 6곳 (기관 1, 대학 2, 기업 3) + 시연 계정 2개
--  * 새 장비 268대: 제조사·모델명·사양은 제조사 공개자료 기준의 실제 제품,
--    보유 조직·요금·가동률·가용 상태·예상 비용은 전부 가상 → is_mock=TRUE
--    (출처에서 확인한 사양은 REAL, 추정치는 MOCK/DEMO_ONLY 로 구분)
--  * 기존 장비(ASTRA-CAND-xxxx)는 가상 조직 소속이 되므로 is_mock=TRUE 로 두고
--    실제 기관 자료를 가리키던 출처(source_url·source_file·source_page)를 비움
--  * 이 파일은 docs/design/tools/gen_v8.py 가 equipment_catalog.json 으로 생성 (난수는 모델명 해시라 매번 같은 결과).
--    이미 적용된 마이그레이션이므로 다시 생성해서 덮어쓰지 말 것 (Flyway 체크섬)
-- =====================================================================

-- 1. 기존 조직 → 가상 이름
UPDATE organizations SET org_type='INSTITUTION', name='한빛뿌리기술지원센터', parent_name=NULL WHERE org_type='INSTITUTION' AND name='한국생산기술연구원 진주뿌리기술지원센터';
UPDATE organizations SET org_type='INSTITUTION', name='미리내우주환경시험센터', parent_name='미리내테크노파크' WHERE org_type='INSTITUTION' AND name='대전테크노파크 우주·양자산업센터';
UPDATE organizations SET org_type='INSTITUTION', name='미리내첨단제조지원센터', parent_name='미리내테크노파크' WHERE org_type='INSTITUTION' AND name='대전테크노파크 국방·로봇·첨단제조센터';
UPDATE organizations SET org_type='INSTITUTION', name='가람재료시험연구원', parent_name=NULL WHERE org_type='INSTITUTION' AND name='한국재료연구원';
UPDATE organizations SET org_type='UNIVERSITY', name='가온대학교 첨단소재분석센터', parent_name='가온대학교' WHERE org_type='INSTITUTION' AND name='경상국립대학교 첨단소재분석지원센터';
UPDATE organizations SET org_type='INSTITUTION', name='다온신뢰성시험센터', parent_name=NULL WHERE org_type='INSTITUTION' AND name='한국신뢰성기술센터';
UPDATE organizations SET org_type='UNIVERSITY', name='새별대학교 로봇연구소', parent_name='새별대학교' WHERE org_type='INSTITUTION' AND name='전남대학교 로봇연구소(마이크로의료로봇센터)';
UPDATE organizations SET org_type='INSTITUTION', name='마루기술지원센터', parent_name=NULL WHERE org_type='INSTITUTION' AND name='기술지원센터';
UPDATE organizations SET org_type='INSTITUTION', name='미리내반도체에너지센터', parent_name='미리내테크노파크' WHERE org_type='INSTITUTION' AND name='대전테크노파크 반도체·에너지산업센터';

-- 2. 기존 장비: 가상 조직 소속이므로 시연 데이터로 표시하고 실제 기관 출처를 비움
UPDATE equipment SET is_mock=TRUE, source_url=NULL, source_file=NULL, source_page=NULL WHERE external_id LIKE 'ASTRA-CAND-%';

-- 3. 새 가상 조직 (승인 상태)

-- 4. 시연 계정 추가 (비밀번호는 V3 시연 계정과 같음): 대학 담당자, 장비를 보유한 기업 회원
SELECT o.id, 'univ1@astra.demo', '$2a$10$VEreyAS6ogOggY/RG5UviOv/iWYbRMrLr95dWutc5hK2y6hsJXvci', '최대학', '055-000-0004', 'INSTITUTION_MANAGER', 'ACTIVE', a.id, now()
FROM organizations o, users a WHERE o.org_type='UNIVERSITY' AND o.name='늘해랑대학교 항공우주공동기기원' AND a.email='admin@astra.demo';
SELECT o.id, 'company2@astra.demo', '$2a$10$VEreyAS6ogOggY/RG5UviOv/iWYbRMrLr95dWutc5hK2y6hsJXvci', '정기업', '055-000-0005', 'COMPANY_USER', 'ACTIVE', a.id, now()
FROM organizations o, users a WHERE o.org_type='COMPANY' AND o.name='미르항공정밀' AND a.email='admin@astra.demo';

-- 5. 시연 장비 (ASTRA-DEMO-xxxx)
